<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shadcn@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
